import React from "react";
import st from './skeleton.module.scss';

export const CircleSkeleton: React.FC<{ size?: string; className?: string }> = ({ 
  size = "80px", 
  className 
}) => (
  <div 
    className={`${st.circleSkeleton} ${className || ''}`}
    style={{ width: size, height: size }}
  ></div>
);

export const LineSkeleton: React.FC<{ width?: string; height?: string; className?: string }> = ({ 
  width = "100%", 
  height = "16px", 
  className 
}) => (
  <div 
    className={`${st.lineSkeleton} ${className || ''}`}
    style={{ width, height }}
  ></div>
);

export const ProfileSkeleton: React.FC = () => (
  <div className={st.profileSkeleton}>
    <CircleSkeleton size="120px" className={st.profileSkeleton__avatar} />
    <div className={st.profileSkeleton__info}>
      <LineSkeleton width="200px" height="24px" />
      <LineSkeleton width="150px" height="20px" />
      <LineSkeleton width="250px" height="16px" />
    </div>
    <div className={st.profileSkeleton__stats}>
      <CircleSkeleton size="60px" />
      <CircleSkeleton size="60px" />
    </div>
  </div>
);

export const ArtifactsSkeleton: React.FC<{ count?: number }> = ({ count = 6 }) => (
  <div className={st.artifactsSkeleton}>
    <LineSkeleton width="200px" height="28px" className={st.sectionTitle} />
    <div className={st.artifactsGrid}>
      {Array.from({ length: count }).map((_, index) => (
        <div key={index} className={st.artifactItem}>
          <CircleSkeleton size="100px" />
          <LineSkeleton width="80px" height="16px" />
        </div>
      ))}
    </div>
  </div>
);

export const BranchesSkeleton: React.FC<{ count?: number }> = ({ count = 4 }) => (
  <div className={st.branchesSkeleton}>
    <LineSkeleton width="200px" height="28px" className={st.sectionTitle} />
    <div className={st.branchesGrid}>
      {Array.from({ length: count }).map((_, index) => (
        <div key={index} className={st.branchItem}>
          <CircleSkeleton size="70px" />
          <div className={st.branchInfo}>
            <LineSkeleton width="120px" height="18px" />
            <LineSkeleton width="80px" height="14px" />
          </div>
        </div>
      ))}
    </div>
  </div>
);

export const PageSkeleton: React.FC = () => {
  return (
    <div className={st.pageSkeleton}>
      <ProfileSkeleton />
      <div className={st.skeletonContent}>
        <BranchesSkeleton />
        <ArtifactsSkeleton />
      </div>
    </div>
  );
};

export default PageSkeleton;
